import { accountDescriptions } from "./accountsDescriptions.js"

export interface CounterpartInfo {
    number: string
    label: string
}

export interface AccountEntry {
    number: string
    slug: string
    label: string
    description?: string
    classNumber: number
    className: string
    type: "bilan" | "résultat"
    side: "actif" | "passif" | "actif ou passif" | "charge" | "produit"
    isOptional: boolean
    parent: string | null
    usageTips: string[]
    counterpart: CounterpartInfo
    debitMeaning: string
    creditMeaning: string
}

function toSlug(number: string): string {
    return number
}

function defineAccount(
    number: string,
    label: string,
    options: {
        description?: string
        classNumber: number
        className: string
        type: "bilan" | "résultat"
        side: "actif" | "passif" | "actif ou passif" | "charge" | "produit"
        isOptional: boolean
        parent: string | null
        counterpart: CounterpartInfo
        usageTips: string[]
        debitMeaning: string
        creditMeaning: string
    },
): AccountEntry {
    return {
        number,
        slug: toSlug(number),
        label,
        description:
            [
                options.description,
                accountDescriptions[number],
            ]
                .filter(Boolean)
                .join(" ") || undefined,
        classNumber: options.classNumber,
        className: options.className,
        type: options.type,
        side: options.side,
        isOptional: options.isOptional,
        parent: options.parent,
        counterpart: options.counterpart,
        usageTips: options.usageTips,
        debitMeaning: options.debitMeaning,
        creditMeaning: options.creditMeaning,
    }
}

